DROP TABLE IF EXISTS `alertes`;
CREATE TABLE `alertes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `niveau` enum('prioritaire','action','info') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'action' COMMENT 'alerte prioritaire, action à traiter, information',
  `cle` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'type et objet : une alerte par sujet',
  `message` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lien` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `etat` enum('ouverte','reportee','ignoree') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ouverte',
  `reportee_au` date DEFAULT NULL,
  `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `maj_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cle` (`cle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `alertes` VALUES (3,'proche','prioritaire','proche:c8','« Orquesta y Coro Nacionales de España », 27 novembre 2026 : il manque lien source (page de l\'organisateur), lien de billetterie ou page de l\'organisateur.','page=concert&id=8','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(4,'proche','prioritaire','proche:c9','« In Between trance », 3 décembre 2026 : il manque lien source (page de l\'organisateur), lien de billetterie ou page de l\'organisateur.','page=concert&id=9','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(5,'extrait','info','extrait:aucun','Aucun extrait de l\'agence n\'a encore été importé.','page=imports','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(6,'vide','info','vide:disques','Albums sans lien d\'écoute ni de commande : Unsuk Chin, Viola Concertos, Ligeti.','page=disques','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(7,'vide','info','vide:articles','Articles sans citation : Le Monde, The Guardian, Gramophone.','page=presse','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(8,'vide','info','vide:telechargements','Téléchargements « à venir » : Biographie, en français, Biographie, en anglais, Photographies, Identité visuelle.','page=contenu&type=telechargements','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(17,'proche','prioritaire','proche:c10','« Concert de Noël », 18 décembre 2026 : il manque lien source (page de l\'organisateur), lien de billetterie ou page de l\'organisateur.','page=concert&id=10','ouverte',NULL,'2026-11-27 13:56:53','2026-11-27 19:30:29'),(25,'vide','info','vide:exemples','8 faux articles de maquette sont dans la revue de presse : à supprimer avant la mise en production.','page=presse','ouverte',NULL,'2026-11-27 15:06:14','2026-11-27 19:30:29'),(30,'vide','action','vide:traductions-en','5 traductions proposées par l\'IA attendent une validation (anglais) : elles ne paraissent pas sur le site d\'ici là.','page=langues&onglet=traductions&langue=en&statut=proposee','ouverte',NULL,'2026-11-27 15:32:21','2026-11-27 15:32:21'),(36,'communication','action','communication:sans-action','3 concerts annoncés dans les 30 jours n\'ont aucune action de communication enregistrée : « Orquesta y Coro Nacionales de España » (27 novembre), « In Between trance » (3 décembre), « Concert de Noël » (18 décembre).','page=editorial#concerts','ouverte',NULL,'2026-11-27 19:30:29','2026-11-27 20:21:38');
DROP TABLE IF EXISTS `annuaire`;
CREATE TABLE `annuaire` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `categorie` enum('orchestre','ensemble','salle','festival','soliste','compositeur','maison_de_disques','media','photographe','producteur','agence') COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom_provisoire` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'le vrai nom reste à fournir : le site n''affiche que la ville',
  `autres_noms` text COLLATE utf8mb4_unicode_ci COMMENT 'un par ligne',
  `ville_fr` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `ville_en` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `pays_fr` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `pays_en` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `langue` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'média : langue principale',
  `latitude` decimal(8,5) DEFAULT NULL,
  `longitude` decimal(8,5) DEFAULT NULL,
  `verifie` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ville et coordonnées de référence vérifiées',
  `fuseau` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `site` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `premiere_collaboration` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'AAAA, AAAA-MM ou AAAA-MM-JJ',
  `mots_diese` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `credit` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `logo_id` int unsigned DEFAULT NULL COMMENT 'médiathèque',
  `typo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'média sans logo : traitement typographique de son nom sur le site',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modifie_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `categorie` (`categorie`),
  KEY `nom` (`nom`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
