DROP TABLE IF EXISTS `articles`;
CREATE TABLE `articles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `cle` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'critique_concert, critique_album, portrait, interview, actualite, autre',
  `media_id` int unsigned DEFAULT NULL COMMENT 'annuaire : le titre de presse, qui porte aussi le logo',
  `titre_fr` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `titre_en` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `chapeau_fr` text COLLATE utf8mb4_unicode_ci,
  `auteur` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `date_article` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'AAAA-MM-JJ ou AAAA-MM ; vide si inconnue',
  `verbatim` text COLLATE utf8mb4_unicode_ci COMMENT 'cité dans sa langue',
  `langue` char(2) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `resume_fr` text COLLATE utf8mb4_unicode_ci,
  `resume_en` text COLLATE utf8mb4_unicode_ci,
  `infos_fr` text COLLATE utf8mb4_unicode_ci COMMENT 'informations complémentaires',
  `lien` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `url_canonique` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `publie` tinyint(1) NOT NULL DEFAULT '1',
  `une` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'à la une : marque éditoriale, indépendante de la publication',
  `accueil` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'sélectionné pour la page d''accueil',
  `ordre_accueil` int NOT NULL DEFAULT '0',
  `largeur` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'sur l''accueil : 1, 2 ou 4 colonnes',
  `exemple` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'faux article de maquette, à supprimer avant la mise en production',
  `origine` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main' COMMENT 'main, url (importé d''une adresse), texte (texte collé)',
  `texte_source` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'texte de l''article récupéré ou collé : sert à vérifier les citations, ne sort jamais sur le site',
  `ordre` int NOT NULL DEFAULT '0',
  `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `articles` VALUES (1,'fanfare','',50,'À propos de *Ravel Abroad*','On *Ravel Abroad*',NULL,'Colin Clarke','','“A simply astonishing disc.”','en','','',NULL,'','',1,0,0,0,1,0,'main',NULL,0,'2026-11-27 14:39:18'),(2,'le-monde','',51,'Portrait','Profile',NULL,'Pierre Gervasoni','2024-06-22','','fr','','',NULL,'https://www.lemonde.fr/culture/article/2024/06/22/pierre-bleuse-directeur-musical-de-l-ensemble-intercontemporain-veut-faire-entendre-tout-ce-qui-se-passe-sur-la-planete_6242263_3246.html','',1,0,0,1,1,0,'main',NULL,1,'2026-11-27 14:39:18'),(3,'the-guardian','',52,'Critique du disque *Unsuk Chin*','Review of the *Unsuk Chin* album',NULL,'Fiona Maddocks','2026-02-13','','en','','',NULL,'https://www.theguardian.com/music/2026/feb/13/ensemble-intercontemporain-unsuk-chin-album-review-pierre-bleuse-samuel-favre-dimitri-vassilakis-gougalon-double-concerto','',1,0,0,2,1,0,'main',NULL,2,'2026-11-27 14:39:18'),(4,'gramophone','',53,'Critique du disque *Ligeti*','Review of the *Ligeti* album',NULL,'Richard Whitehouse','2024-06','','en','','',NULL,'https://gramophone.co.uk/review/ligeti-concertos-and-chamber-music-bleuse','',1,0,0,3,1,0,'main',NULL,3,'2026-11-27 14:39:18'),(5,'exemple-contrepoint','',77,'Pierre Bleuse, la clarté comme manifeste','Pierre Bleuse: clarity as a manifesto',NULL,'Claire Duvernay','2026-10-08','« Sous sa baguette, la partition la plus dense devient lisible comme une page d’écriture. »','fr','Rencontre avec le directeur musical de l’Ensemble intercontemporain, entre deux répétitions, sur la transmission du répertoire d’aujourd’hui.','An interview with the music director of the Ensemble intercontemporain, between two rehearsals, on passing on today’s repertoire.',NULL,'https://example.com/contrepoint/pierre-bleuse','',1,0,1,0,4,1,'main',NULL,4,'2026-11-27 14:39:18'),(6,'exemple-the-score','',78,'Critique du disque *Ligeti*','Review of the *Ligeti* album',NULL,'Hannah Whitcombe','2026-09-19','“Precise without ever being cold, this is Ligeti with a pulse.”','en','Le critique salue une lecture des concertos à la fois rigoureuse et chantante, servie par une prise de son d’une grande transparence.','The reviewer praises a reading of the concertos both rigorous and lyrical, served by a recording of great transparency.',NULL,'https://example.com/the-score/ligeti-review','',1,0,1,1,2,1,'main',NULL,5,'2026-11-27 14:39:18'),(7,'exemple-klangbild','',79,'Un chef français à Stuttgart','A French conductor in Stuttgart',NULL,'Stefan Kranich','2026-07-02','„Ein Dirigent, der zuhört, bevor er gestaltet.“','de','Compte rendu d’un concert avec le SWR Symphonieorchester, où la *Symphonie fantastique* retrouve sa part de rêve et d’inquiétude.','A concert review with the SWR Symphonieorchester, in which the *Symphonie fantastique* regains its share of dream and unease.',NULL,'https://example.com/klangbild/stuttgart','',1,0,1,2,2,1,'main',NULL,6,'2026-11-27 14:39:18'),(8,'exemple-echo-lyrique','',80,'Prades, un festival qui respire','Prades, a festival that breathes',NULL,'Julien Morel','2026-08-14','« Le Festival Pablo Casals a trouvé en lui un hôte autant qu’un directeur. »','fr','Retour sur l’édition 2026 du Festival Pablo Casals, sa programmation entre musique de chambre et créations, et l’abbaye Saint-Michel-de-Cuxa comme écrin.','A look back at the 2026 Pablo Casals Festival, its programme between chamber music and premieres, set in the abbey of Saint-Michel-de-Cuxa.',NULL,'https://example.com/echo-lyrique/prades-2026','',1,0,1,3,1,1,'main',NULL,7,'2026-11-27 14:39:18'),(9,'exemple-mesures','',81,'*Répons*, l’espace pour instrument','*Répons*, with space as an instrument',NULL,'Margot Lefèvre','2026-05-27','« Une architecture sonore qui tourne autour de l’auditeur, et le tient en haleine. »','fr','À la Philharmonie de Paris, l’Ensemble intercontemporain redonne l’œuvre emblématique de Pierre Boulez dans un dispositif spatialisé.','At the Philharmonie de Paris, the Ensemble intercontemporain revives Pierre Boulez’s emblematic work in a spatialised set-up.',NULL,'https://example.com/mesures/repons','',1,0,1,4,1,1,'main',NULL,8,'2026-11-27 14:39:18'),(10,'exemple-podium','',82,'Une soirée Unsuk Chin éblouissante','A dazzling Unsuk Chin evening',NULL,'Daniel Ashworth','2026-03-11','“Every colour in its place, every gesture with a purpose.”','en','Le concert de sortie du disque consacré à Unsuk Chin, entre virtuosité des solistes et cohésion de l’ensemble.','The launch concert of the Unsuk Chin album, between the soloists’ virtuosity and the ensemble’s cohesion.',NULL,'https://example.com/podium/unsuk-chin','',1,0,1,5,1,1,'main',NULL,9,'2026-11-27 14:39:18'),(11,'exemple-gazette','',83,'Ravel, d’un continent à l’autre','Ravel, from one continent to another',NULL,'Antoine Valcourt','2026-01-23','« Un Ravel voyageur, d’une élégance qui n’exclut jamais le risque. »','fr','Le disque *Ravel Abroad* éclaire les échos de l’Amérique et de l’Espagne dans l’œuvre du compositeur.','The *Ravel Abroad* album sheds light on the echoes of America and Spain in the composer’s work.',NULL,'https://example.com/gazette/ravel-abroad','',1,0,1,6,1,1,'main',NULL,10,'2026-11-27 14:39:18'),(12,'exemple-nordisk','',84,'Cinq saisons à Odense','Five seasons in Odense',NULL,'Ida Halvorsen','2025-12-05','“He leaves an orchestra that plays with one breath.”','en','Bilan du mandat de chef principal à l’Orchestre symphonique d’Odense, des grandes symphonies aux commandes passées aux compositeurs danois.','An assessment of his tenure as Chief Conductor of the Odense Symphony Orchestra, from the great symphonies to commissions from Danish composers.',NULL,'https://example.com/nordisk/odense','',1,0,0,7,1,1,'main',NULL,11,'2026-11-27 14:39:18');
DROP TABLE IF EXISTS `articles_citations`;
CREATE TABLE `articles_citations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `article_id` int unsigned NOT NULL,
  `texte` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'la citation, dans sa langue et sa formulation d''origine, avec ses guillemets',
  `langue` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'langue d''origine de la citation',
  `traduction_fr` text COLLATE utf8mb4_unicode_ci COMMENT 'traduction dans la langue de référence ; vide si la citation est déjà dans cette langue',
  `principale` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'la citation mise en avant : une par article',
  `verifiee` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 : proposée par l''IA, formulation à vérifier dans l''article',
  `ordre` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `article_id` (`article_id`,`ordre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `articles_citations` VALUES (1,1,'“A simply astonishing disc.”','en',NULL,1,1,0),(2,5,'« Sous sa baguette, la partition la plus dense devient lisible comme une page d’écriture. »','fr',NULL,1,1,0),(3,6,'“Precise without ever being cold, this is Ligeti with a pulse.”','en',NULL,1,1,0),(4,7,'„Ein Dirigent, der zuhört, bevor er gestaltet.“','de',NULL,1,1,0),(5,8,'« Le Festival Pablo Casals a trouvé en lui un hôte autant qu’un directeur. »','fr',NULL,1,1,0),(6,9,'« Une architecture sonore qui tourne autour de l’auditeur, et le tient en haleine. »','fr',NULL,1,1,0),(7,10,'“Every colour in its place, every gesture with a purpose.”','en',NULL,1,1,0),(8,11,'« Un Ravel voyageur, d’une élégance qui n’exclut jamais le risque. »','fr',NULL,1,1,0),(9,12,'“He leaves an orchestra that plays with one breath.”','en',NULL,1,1,0);
DROP TABLE IF EXISTS `articles_concerts`;
CREATE TABLE `articles_concerts` (
