  `debut_le` datetime DEFAULT NULL,
  `fin_le` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `statut` (`statut`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
