DROP TABLE IF EXISTS `textes`;
CREATE TABLE `textes` (
  `cle` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'description, citation, biographie, saison, lettre, credit',
  `fr` text COLLATE utf8mb4_unicode_ci,
  `en` text COLLATE utf8mb4_unicode_ci,
  `modifie_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`cle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `textes` VALUES ('biographie','Pierre Bleuse est directeur musical de l\'Ensemble intercontemporain et directeur artistique du Festival Pablo Casals de Prades. Chef principal de l\'Orchestre symphonique d\'Odense de 2021 à 2026, il est l\'invité d\'orchestres comme le Royal Concertgebouw Orchestra, le London Philharmonic Orchestra, l\'Orchestre de Paris ou le Tokyo Symphony Orchestra.\n\nVioloniste de formation, il dirige le grand répertoire symphonique et la musique d\'aujourd\'hui avec la même attention : faire dialoguer les œuvres plutôt que les opposer.','Pierre Bleuse is Music Director of the Ensemble intercontemporain and Artistic Director of the Pablo Casals Festival in Prades. Chief Conductor of the Odense Symphony Orchestra from 2021 to 2026, he is a guest of orchestras including the Royal Concertgebouw Orchestra, the London Philharmonic Orchestra, the Orchestre de Paris and the Tokyo Symphony Orchestra.\n\nA violinist by training, he brings the same attention to the great symphonic repertoire and to the music of today, letting works speak to one another rather than setting them apart.','2026-11-13 10:37:45'),('citation','« Plus je progresse, plus je me sens libre »','“The further I progress, the freer I feel”','2026-11-27 20:30:02'),('credit','Site en construction · musiques : Tchaïkovski, Symphonie n° 6, IV, Musopen (domaine public) ; Berlioz, *Symphonie fantastique*, SWR Symphonieorchester (ARD Klassik) ; *The Centenary of Pierre Boulez*, Ensemble intercontemporain & Friends (ARTE Concert)','Website in progress · music: Tchaikovsky, Symphony No. 6, IV, Musopen (public domain); Berlioz, *Symphonie fantastique*, SWR Symphonieorchester (ARD Klassik); *The Centenary of Pierre Boulez*, Ensemble intercontemporain & Friends (ARTE Concert)','2026-11-27 15:21:39'),('description','Site officiel de Pierre Bleuse, chef d\'orchestre : agenda des concerts, biographie, disques, presse, contacts.','Official website of conductor Pierre Bleuse: concert schedule, biography, recordings, press, contacts.','2026-11-13 10:37:45'),('lettre','Les concerts du mois et les actualités, une fois par mois.','The month\'s concerts and news, once a month.','2026-11-13 10:37:45'),('saison','Saison 2026-2027','2026/27 season','2026-11-13 10:37:45');
DROP TABLE IF EXISTS `traductions`;
CREATE TABLE `traductions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `objet` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'table de l''objet traduit',
  `objet_id` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'clé de la ligne : identifiant, ou clé texte',
  `champ` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `langue` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `texte` mediumtext COLLATE utf8mb4_unicode_ci,
  `statut` enum('validee','proposee') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'validee' COMMENT 'proposee : proposée par l''IA, ne sort pas sur le site',
  `origine` enum('main','ia','reprise') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main',
  `empreinte` char(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'MD5 du texte de référence au moment de la traduction : s''il a changé, la traduction est à revoir',
  `modifie_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `objet` (`objet`,`objet_id`,`champ`,`langue`),
  KEY `langue` (`langue`,`statut`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `traductions` VALUES (1,'textes','biographie','texte','en','Pierre Bleuse is Music Director of the Ensemble intercontemporain and Artistic Director of the Pablo Casals Festival in Prades. Chief Conductor of the Odense Symphony Orchestra from 2021 to 2026, he is a guest of orchestras including the Royal Concertgebouw Orchestra, the London Philharmonic Orchestra, the Orchestre de Paris and the Tokyo Symphony Orchestra.\n\nA violinist by training, he brings the same attention to the great symphonic repertoire and to the music of today, letting works speak to one another rather than setting them apart.','validee','reprise','2d657be2fca4f028e6132172941ec3b4','2026-11-27 13:59:32'),(2,'textes','citation','texte','en','“The further I progress, the freer I feel”','validee','reprise','0621ad872ce229cb47ff3d1e3e16c873','2026-11-27 13:59:32'),(3,'textes','credit','texte','en','Website in progress · music: Tchaikovsky, Symphony No. 6, IV, Musopen (public domain); Berlioz, *Symphonie fantastique*, SWR Symphonieorchester (ARD Klassik); *The Centenary of Pierre Boulez*, Ensemble intercontemporain & Friends (ARTE Concert)','validee','reprise','f2c94869e5a8154b51db194bad64b857','2026-11-27 13:59:32'),(4,'textes','description','texte','en','Official website of conductor Pierre Bleuse: concert schedule, biography, recordings, press, contacts.','validee','reprise','f06663ec16d3583ac3fd3ae394fc828d','2026-11-27 13:59:32'),(5,'textes','lettre','texte','en','The month\'s concerts and news, once a month.','validee','reprise','b69e33a9e6b3c57a104cf88d79b3f30f','2026-11-27 13:59:32'),(6,'textes','saison','texte','en','2026/27 season','validee','reprise','570d1f6b069393fec66145ada56c896e','2026-11-27 13:59:32'),(7,'concerts','1','pays','en','Sweden','validee','reprise','b7062d106ff8a5f54b526307fbaf762d','2026-11-27 13:59:32'),(8,'concerts','2','mentions','en','Debut with the orchestra','validee','reprise','b25e06df10101c8d5fe61129186d7a4e','2026-11-27 13:59:32'),(9,'concerts','3',